ORDER BY t.created_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT  
WHERE t.tenant_id = #{tenantId} AND t.deleted_at IS NULL AND t.biz_code = #{bizCode}
  AND t.env = #{env} AND t.app_code = #{appCode} AND t.config_key = #{resourceName}
  AND t.status IN #{status}
ORDER BY t.created_at DESC, t.id DESC LIMIT 1

mapper.update:
UPDATE ddc_publish_task SET updated_at = #{claimedAt}, version = version + 1,
    update_user_id = #{actor}, update_time = CURRENT_TIMESTAMP AT TIME ZONE 'UTC'
WHERE tenant_id = #{tenantId} AND change_id = #{changeId} AND deleted_at IS NULL
  AND status IN #{status}
  AND updated_at < #{staleBefore}

UPDATE ddc_publish_task SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{et.updateUserId}, update_time = #{et.updateTime}
WHERE tenant_id = #{et.tenantId} AND id = #{et.id} AND version = #{et.version} AND deleted_at IS NULL
